B=Path('/workspace/work/tutorial-audit-20261008'); M=json.loads((B/'manifest.json').read_text()); P={p['page_id']:p for p in M['inventory']['pages']}; notes=[]
def q(pid,quote):
 raw=Path(P[pid]['snapshot']).read_text(); assert quote in raw,(pid,quote)
 return {'page_id':pid,'line':raw[:raw.index(quote)].count('\n')+1,'quote':quote}
def add(pid,focus,quote,prior,mechanism,need,transition,limits='',status='sufficient',extra=None):
 notes.append({'page_id':pid,'source_sha256':P[pid]['source_sha256'],'source_judgment':status,'reading_scope':'full main via continuity_source.py; details excluded','current_understanding_required':focus,'quoted_basis':[q(pid,quote)],'actual_dependencies':prior,'checks':[{'focus':focus,'mechanism':{'judgment':'sufficient','answer':mechanism,'basis':'quoted_basis plus actual_dependencies'},'need':{'judgment':'sufficient','answer':need,'basis':'quoted_basis plus actual_dependencies'}}]+(extra or []),'transition':transition,'limits_and_unverified':limits or '未執行程式或追查runtime原始數字；只判正文給出的銜接與結論邊界。','issues':[]})
add('chapter-19','從零零件整合到有限成品的章級學習問題','現在把這些零件接成一個可以使用的成品：打字、看商品圖、讀指定字卡與聽客服錄音，都由同一個文字核心生成回答。',[], '共同核心回答，感知入口供材料；本頁導覽不要求提前教完內部演算法。','格式要求也須隨材料傳入；從分立任務走到共同成品有明確目的。','先看真回答→拆結構/資料/訓練→19.12驗收；20章不同成熟起點。')
add('19.1','多入口與歷史條件須各別改動核對','例如，把兩格商品圖左右交換，回答也應交換；把「兩點」改成「一句」，內容仍應正確而格式改變。',['chapter-19','12.16'],'文字/history直接進核心，感知材料先變向量；歷史確認是公開輸入，最後兩點是生成。','一題只有文字路線；改材料、範圍、格式才知道是否用到不同條件。','19.2核心結構；19.6感知與19.7工具；19.12整體成功率。','MoE完整內部待19.2，EOS此頁已說回答結束；公開成功與總體能力不同。圖640/360實看。')
add('19.2','Dense與MoE結構計數、權重共享與比較邊界','本章 MoE 一個位置用兩組 FFN，Dense 用一組，所以這個配對不是同計算量或同記憶體的比較。',['15.1','15.2','15.3','15.4','15.13','14.6'],'四expert選二加權，tied embedding真同一張表只數一次；隨機模型只驗結構。','把已教路由整合進多模態作觀察，Dense同寬同層提供另一真成品；來源不宣稱隔離架構勝因。','結構計數不能回答學會什麼，19.12生成題驗收。','固定width/layers數值屬可重做的成品設定，未承諾最佳超參數；550詞表由補充詳查，不影響此頁計數定義。')
add('19.3','資料家族衍生與train/validation/test用途','先決定家族去哪份資料，再製作不同問法與版本。',['19.1'],'原圖/配對/換位同份，配對兩來源也需同份；題目數不等於素材數。','排除來源跨份重複，避免見過素材冒稱陌生；仍另查答案分布及換位控制。','固定資料後追查19.4權重鏈；19.6及19.12看材料使用。','12字/兩字體已學過；錄音不是人數；speaker泛化未驗，均正文直接交代。圖640/360實看。')
add('19.4','不同訓練階段、更新範圍、init與resume狀態界線','--resume`：恢復同一段',['19.2','19.3'],'每新段接自己的best權重，重建optimizer/seed抽樣/计数；同段latest恢復完整狀態和原目標。感知先學分類，joint固定骨幹/head更新核心/接頭。','維持原核心而增加材料，不能同名隨機檔冒充接續；weighted/native改誤差重視份量，不是答對證據。','下一節教SFT示範；19.11再區分推論包與完整工作檔。','文字pretrain有限範圍；native4000完成與1000選定分開。未執行紀錄讀取程式。圖640/360實看。',extra=[{'focus':'weighted與native目標轉換','mechanism':{'judgment':'sufficient','answer':'同模型同資料，工具/數字/原聲音示範代價比重改變。'},'need':{'judgment':'sufficient','answer':'本段要追蹤實際學習安排與接續狀態；19.8明確說讓既有示範更新更受重視，沒有保證效果。'},'basis':q('19.4','末兩段仍使用同一模型和資料，只改訓練誤差的比重。')}])
add('19.5','SFT條件變化與assistant目標位置','問題與歷史仍在輸入裡，但作答代價只計 assistant 的文字與結束標記 EOS。',['19.3','19.4','7.4','7.17'],'角色/條件保留輸入，assistant+EOS目標，-100不計代價；標籤整理不是更新。','缺資訊/工具不可用/超範圍示範與能直接回答題配合，教選行為而非每題求助。','保留回答規則，19.6只換本輪材料；19.12分項核對。','無須在此重教完整CE；訓練讀給定前綴與推論讀自己的字明說。')
add('19.6','感知特徵、位置、指定範圍與共同核心生成','只留下「有褲子、有包」的平均摘要，還不夠回答「左邊是什麼」。',['10.6','11.14','11.18','12.15','12.16','18.1','19.4','19.5'],'商品格像素和位置轉向量；字卡先裁框再保留欄位；聲音按時間分16區間；核心最終生成。','不同答案要保留對應內容/位置/範圍/歷史；所給框不是類別答案，平均集合會失去關係。','同核心接完感知後19.7工具，19.12中間入口及真回答分判。','圖三張640/360及三處1280/390原位context實看；沒有播放真錄音或重生成。CTC完整對齊推導待補充，主文已給32欄/短答案的目的及不需逐欄標註。',extra=[{'focus':'soft bridge','mechanism':{'judgment':'sufficient','answer':'特徵與整組分數比例用可調投影接進核心，不先硬選類別查答案表。'},'need':{'judgment':'sufficient','answer':'共同核心可利用候選程度及內容，不被head第一名固定；18.1明說只留第一名丟掉候選關係，本頁head錯而最後答對例允許區分兩者，不是soft bridge優於硬橋的因果證明。'},'basis':q('19.6','意思是還保留多個候選的程度，沒有先挑最大分數的類別，再查表貼一句固定答案。')},{'focus':'續聊歷史狀態','mechanism':{'judgment':'sufficient','answer':'保存原訊息/音訊路徑/真正第一輪assistant，下一輪僅增加新user要求。'},'need':{'judgment':'sufficient','answer':'改格式仍須知道同一App主題；12.16教過保存與模型學會使用兩件事。'},'basis':q('19.6','音訊留在原來那輪，不重新當成目前問題，也沒有用示範答案替換第一輪。')}])
add('19.7','工具請求、真執行、讀回作答的三段邊界','因此「可執行」與「參數符合問題」必須分開判定。',['19.1','19.5','19.6'],'模型生成JSON，程式驗欄位/整數/範圍再真乘，assistant呼叫+tool結果回填後第二次生成。','計算器只保證所收參數正算，抄错数字会偏离原需求；需核整鏈不能只看416。','19.12成功例與最後0/276不混；可替換返回值作依賴檢查但正常率用真結果。','手寫raw程式只測解析執行；不是神經生成。圖640/360實看。')
add('19.8','後訓練方法按學習訊號選，不串成必經工序','方法要對應現在缺少的學習訊號。',['7.17','7.20','13.17','19.4','19.5'],'SFT理想回覆、DPO偏好對與reference、PPO新生成+可信評分分路；本成品joint仍示範目標。','格式缺示範先補條件，已有兩份好答案才有偏好比較；MTP添未來目標不直接解決入口/工具問題。','選成品後19.9推論包裝效率，仍檢舊能力保留。','選擇屬方法總覽；完整PPO/DPO更新已前章展開，不在此再推導。不能外加隨機MTP頭當學會。')
add('19.9','KV cache及最佳化介面保持前文語意','但省下重算以前，必須確認前文、位置與可讀範圍仍相同，否則兩條路可能已在回答不同問題。',['14.1','14.2','14.6','15.4','16.3','16.4','16.5','16.8','16.14'],'cache沿用各層K/V，5格整讀和3+2格最后候選比較；RoPE/RMS/GQA/tied/SDPA各有已讀前文機制。','避免重复旧位置工作且要等價；SDPA介面不保證FlashAttention，packing/MTP/speculative未採用。','19.10再看部署儲存；較快需要同硬體權重生成條件量測。','隨機微例仅核數值，eval/no_grad作用明說；未跑速度或微例。Flash backend在來源本身標未支持，不當缺陷。')
add('19.10','參數儲存、RAM與縮小方法的差別','少用一部分計算，並沒有把其他權重從 RAM 移走。',['19.2','19.9','17.1','18.1','18.2'],'所有expert仍存；FP32四bytes按學參數只數一次；量化改位元，蒸餾先選小學生。','部署要同看檔案/運行資源/答案保留，計算稀疏不能代RAM下降。','19.11交付檔案角色；19.12不同路線能力。','理想2bytes減半不是完成量化；V2沒有驗收量化蒸餾，Dense不是MoE學生。')
add('19.11','推論公開包、新段起點與恢復工作包用途','只拿到回答器的權重，不能還原這些狀態。',['19.4','19.10'],'四公開檔權重/結構/字表/清單，指紋+完整權重檢查；自己的best新段/latest同段恢復。','要回答需配對零件，精確續跑另需optimizer/亂數/取樣/進度；固定revision重現同批檔。','19.12能力驗收；20章沿用成熟模型的另一配置。','圖640/360實看；公開safetensors非trainer起點限制是此實作約定，正文完整交代。')
add('19.12','整體能力按任務、鏈、分母與來源限定驗收','高分任務不能抵銷另一項未達標。',['19.1','19.3','19.4','19.5','19.6','19.7','19.10','19.11'],'3734題固定評分，入口CTC完整串與核心生成分列，工具返回與真往返分列，真續聊用自己歷史。','回答最初同核心會什麼問題，不能讓單獨入口/高分類/完成訓練遮住工具/語音/範圍失敗。','20章換Qwen/Whisper成熟起點，明示不接續MoE也不補分。','各speaker/字體/框/類別限制已在19.3/6鋪好；未追查原始metrics，数字仅核正文解释与边界。')
add('chapter-20','成熟底座應用／候選微調與主線成品分開','它讓我們研究已具備能力的模型如何應用、微調與驗收，與第19章所有神經元件從隨機權重訓練的主線有不同起點。',['19.12'],'Qwen圖文+Whisper逐字稿；候選未採用故原底座。','有成熟能力的另一出發點教應用與驗收，不替小模型補能力。','20.1輸入分工；各節短CPU微例與完整操作入口分開。')
add('20.1','同歷史會合點、ASR與回答分工','ASR 是語音辨識，輸出「聽到哪些字」，不是問題的答案。',['12.14','12.16','chapter-20'],'打字/Whisper逐字稿進同歷史，Qwen處理照片+文字；介面原稿可更正再送出。','換入口仍須保留照片和繁中條件；未更正原稿才是原自動路線評測。','20.2打開成品，20.12用兩路定位失敗。','手寫相同字只示範會合點；LoRA完整機制待20.6，不被當作第二聊天模型。圖640/360實看。')
add('20.2','本機啟動、轉寫/送出/清除與下載開始時點','公開清單下載配置及來源記錄，完整圖文權重在啟動時取得，語音權重等第一次辨識才載入。',['20.1','natural-v4-student'],'逐步文字→照片→錄音聽寫→送出；新對話清素材歷史，localhost服務需終端保持。','分站確認，先知道配置小下載與模型大下載不同，操作通和品質可靠不同。','完整安裝命令可開補充或讀指定學生頁；20.3資源。','natural-v4-student是本組已讀的操作指引，不假定順序讀者先讀；主文基本分工足夠，實做安装细节可选。未启动。')
