add('20.11','区域文字内容、行序与空白要求','這個橫排例子約定上到下、每行左到右。',['11.18','20.10'],'牛奶/麵包颠倒Counter仍同、完整字串不同，换行是要求一部分。','所有字正确不代表按版面串接，裁切需保原位置，不能事后择得分读序。','20.13多行指定顺序1/3与单区分列。','图640/360实看；文本足够交代本次横排约定，没擅自要求教所有直排多栏算法。')
add('20.12','ASR错误与聊天错误两路诊断','正確文字也答錯，就繼續查聊天；正確文字能答、錄音路線不能，則先查ASR的關鍵字。',['12.14','20.1','20.8','20.10'],'同原话一路真稿、一路Whisper实际稿，相同聊天/照片/history；漏不改变条件CER仅11.1。','关键否定词丢失比平均CER更影响需求；先定位输入错误再核回答。','20.13同四问两路2/4结果。','图640/360实看；真人朗读非即兴所有噪声/口音，人工更正结果另算。')
add('20.13','固定配置交付与分用途能力卡','因此178份回答不是178個獨立情境，不合成一個「什麼都會」的總分。',['19.11','19.12','20.1','20.3','20.5','20.8','20.9','20.10','20.11','20.12'],'底座/处理器/ASR/生成设定同份，完整SHA比较；178回答及EOS失败保留分母，多用途不同题型分列。','文件同配对不保能力；动作/读序/聊天弱项与ASR听对仍聊天错不能被读字好成绩遮盖。','学生试用或另建资料与候选，自留新验证最后题。','171+7正常/截断、42共享84问答、两路四问相关性正文可解释；runtime与分项事实仅按来源声明未重核。')
add('natural-v4-student','实际安装、下载、服务、素材状态与离线步骤','這一步只聽寫，尚未請聊天助理回答。',['20.1','20.2','20.3','20.9','20.10','20.11','20.12','20.13'],'固定git/独立venv/CPU或GPU，清单下载2小配置，启服务载Qwen，第一次辨识才载Whisper；localhost/清素材/关闭/缓存各不同。','逐步文字→图→音定位；核原稿/更正再送出，资源数据固定环境不当最低要求。','准备新实验先data再training；先在线完整三路才local-files-only。','完整6765字指引已读；没有实际安装/下载/启动，已有CPU浏览器记录仅为来源声称。GPU/Windows/WSL/Apple范围限定明确。',extra=[{'focus':'下载状态与目录','mechanism':{'judgment':'sufficient','answer':'list列配置；download核大小SHA；verify已有目录；不同内容停止改新目录；缺官方缓存offline停止。'},'need':{'judgment':'sufficient','answer':'知道已取得哪些零件，避免仅配置成功便当音讯模型准备齐全。'},'basis':q('natural-v4-student','第二行只重新檢查這些配置文件，尚未下載完整模型，也不檢查回答能力。')}])
add('natural-v4-data','用途标注、来源/题数/家族及固定快照三种版本','兩者可以使用不同提交，但必須搭配這裡固定的同一份資料清單。',['19.3','20.4','20.5','20.9','20.10','20.11','20.12','natural-v4-student'],'rows图文chat vs audio_rows稿，2077/124/170题与509照片、827裁切、70来源图、38录音分判；本机代码commit/远端data revision/manifest SHA独立核。','让资料实际教所需用途而非增加重复数量；来源家族一起分，转写不助手真值，指纹不保证标注正确。','固定包核→可选用源重建保包bytes→新数据另版→training。','完整9446字已读；外部授权/快照下载/重建未执行。源码编/数据rev不同最低对应要求有表和完整指纹，不需自行猜。',extra=[{'focus':'重建原素材','mechanism':{'judgment':'sufficient','answer':'独立源checkout、Python3.13固定编码包，另一目录reconstruct/verify-manifest；只读部分容器。'},'need':{'judgment':'sufficient','answer':'同视觉不等同bytes，固定代码+编码保实际快照；源不能取相似替代原答案。'},'basis':q('natural-v4-data','即使兩張圖看起來相同，儲存方式不同仍可能得到不同位元組。')}])
add('natural-v4-training','训练更新、续跑保存点、三配置验证、先封选择后测试','這份配方的 `--steps 2077` 指2,077次參數更新，不是只讀2,077題。',['8.8','20.3','20.5','20.6','20.7','20.8','20.9','20.10','20.11','20.12','20.13','natural-v4-student','natural-v4-data'],'两题梯度累积一次step，4154读题/2077更新；只有q/v LoRA更新，输入完整先前缀核再mask，超长报错。','可复做同配方候选、分更新发生与用途改善；不是拿短微例代全模型/ASR训练。','验证固定三配置→规定门槛primary→选底座或adapter封配置→selected-only test→serve同配置。','完整16068字已读；命令/云端/原audit记录未执行或互看。实际配置不是最佳调参承诺。',extra=[{'focus':'最近进度与不可覆盖候选','mechanism':{'judgment':'sufficient','answer':'checkpoint-every更新adapter最近完整状态；checkpoint-steps分别固1039/2077。续跑保持原setting另resumed，pending只要求未经过候选。'},'need':{'judgment':'sufficient','answer':'防把每25步恢复保存当候选；改正路径使验证读实际来源；未保存更新不恢复。'},'basis':q('natural-v4-training','因此它不代表每25步都留下獨立候選。')},{'focus':'验证采纳规则与综合分数','mechanism':{'judgment':'sufficient','answer':'全部132 EOS、逐用途保留，五能力组等权/组内rate均值；严格超过底座，候选同分早者，没有过门槛保底座。'},'need':{'judgment':'sufficient','answer':'不让照片多题吞掉小用途；假设算例照片提高仍正确稿退步，primary高也拒绝。'},'basis':q('natural-v4-training','分數雖高，仍因那一路聊天退步而不能選。')},{'focus':'validation参数和三配置状态','mechanism':{'judgment':'sufficient','answer':'adapter先载1039，comparison第一个同路径、第二个2077、关LoRA得base，不叠加；三者共用真ASR稿，learning-rate不更新。'},'need':{'judgment':'sufficient','answer':'同材料生成约定比较，程序只原始回答/部分统计，人按来源素材逐题判用途后选版。'},'basis':q('natural-v4-training','不是把兩份修正疊在一起。')},{'focus':'定版/最后测试/使用自己配置','mechanism':{'judgment':'sufficient','answer':'base保存model/ASR actual revision、manifest/协议/generation，adapter保存指纹与实际设置；test selected-only无重新候选比较，serve沿同选择。'},'need':{'judgment':'sufficient','answer':'test只描述固定能力，不拿结果换权重；已据错题改则回归，下一版需新考卷。'},'basis':q('natural-v4-training','最後測試不重新比較兩份修正，也不替你選版；不要據此換權重、改答案或換正規化規則。')}])
